checker.py:
"""Автопроверка решений.

Как это работает:
1. Код ученика чистится: убираются обёртки ```, «умные» кавычки и т.п.
2. compile() проверяет синтаксис, и ошибка сразу показывается с номером строки.
3. Каждый тест запускается в своей временной папке, в ОТДЕЛЬНОМ процессе
   (runner.py), с таймаутом и без токена бота в окружении.
4. Вывод или результат сравнивается с ожидаемым, и получается отчёт в HTML для Telegram.

Виды тестов (описаны в файлах course/s*.py):
    {"input": "...", "output": "..."}           — программа: ввод → вывод
        доп. ключи: args, files, expect_files, exit="error", match, check, timeout
    {"setup": "...", "expr": "...", "expected": X}  — функция/класс: выражение → значение
    {"expr": "...", "raises": "ValueError"}          — выражение должно бросить исключение
    задача с kind="pytest"                           — ученик пишет тесты сам
"""

import csv
import html
import io
import json
import os
import re
import subprocess
import sys
import tempfile
import textwrap
from dataclasses import dataclass, field

RUNNER = os.path.join(os.path.dirname(os.path.abspath(__file__)), "runner.py")
TIMEOUT = 3  # секунд на один тест
PYTEST_TIMEOUT = 20  # секунд на один прогон pytest
MAX_CODE = 20_000  # символов в решении

# ------------------------------------------------------------------ результаты


@dataclass
class Outcome:
    """Результат одной проверки."""

    ok: bool
    name: str
    details: str = ""  # HTML с подробностями (для проваленных)
    timeout: bool = False


@dataclass
class Report:
    """Результат проверки решения целиком."""

    outcomes: list = field(default_factory=list)
    fatal: str = ""  # HTML: ошибка, из-за которой тесты не запускались
    skipped: int = 0  # сколько тестов не запускали (после таймаута)

    @property
    def passed(self):
        return sum(outcome.ok for outcome in self.outcomes)

    @property
    def total(self):
        return len(self.outcomes) + self.skipped

    @property
    def ok(self):
        return not self.fatal and self.total > 0 and self.passed == self.total


