# ------------------------------------------------------------------ мелкие помощники


def esc(text):
    """Экранирование для HTML Telegram: только &, < и >."""
    return html.escape(str(text), quote=False)


def pre(text, limit=700):
    """Блок кода для Telegram (обрезается, чтобы сообщение не стало огромным)."""
    text = text if text.strip() else "(пусто)"
    if len(text) > limit:
        text = text[:limit] + "\n…"
    return f"\n<pre>{esc(text)}</pre>\n"


def normalize(text):
    """Приводит вывод к единому виду: переносы строк, пробелы в конце, пустые строки по краям."""
    text = text.replace("\r\r\n", "\n").replace("\r\n", "\n").replace("\r", "\n")
    lines = [line.rstrip() for line in text.split("\n")]
    while lines and not lines[-1]:
        lines.pop()
    while lines and not lines[0]:
        lines.pop(0)
    return "\n".join(lines)


SMART_CHARS = {"“": '"', "”": '"', "„": '"', "‘": "'", "’": "'", "\u00a0": " ", "\u200b": "", "\ufeff": ""}


def clean_code(text):
    """Убирает то, что добавляет Telegram или телефон: ```обёртки```, «умные» кавычки, лишние отступы."""
    text = text.replace("\r\n", "\n")
    for bad, good in SMART_CHARS.items():
        text = text.replace(bad, good)
    fenced = re.fullmatch(r"\s*```[\w+-]*[ \t]*\n(.*?)\n?[ \t]*```\s*", text, re.S)
    if fenced:
        text = fenced.group(1)
    return textwrap.dedent(text).strip("\n") + "\n"


def syntax_problem(code, filename):
    """Проверка синтаксиса без запуска. Возвращает HTML с объяснением или None."""
    try:
        compile(code, filename, "exec")
    except SyntaxError as exc:
        line = (exc.text or "").rstrip("\n")
        pointer = ""
        if exc.offset and line.strip():
            pointer = "\n" + " " * max(exc.offset - 1, 0) + "^"
        title = "Ошибка отступов" if isinstance(exc, IndentationError) else "Синтаксическая ошибка"
        text = f"🧩 <b>{title}</b> в строке {exc.lineno}:\n{pre(line + pointer)}<code>{esc(str(exc.msg))}</code>"
        for needle, hint in SYNTAX_HINTS:
            if needle in str(exc.msg):
                text += f"\n💡 {hint}"
                break
        return text
    except (ValueError, RecursionError, MemoryError, OverflowError) as exc:
        return f"🧩 Не получилось разобрать код: <code>{esc(str(exc))}</code>"
    return None


def write_file(folder, name, content):
    """Создаёт файл (с подпапками). Пишем байты, чтобы переносы строк не зависели от ОС."""
    path = os.path.join(folder, *name.split("/"))
    os.makedirs(os.path.dirname(path), exist_ok=True)
    data = content.encode("utf-8") if isinstance(content, str) else content
    with open(path, "wb") as file:
        file.write(data)


def child_env():
    """Окружение для кода ученика: только системное, без токена бота и прочих секретов."""
    keep = {"SYSTEMROOT", "WINDIR", "PATH", "TEMP", "TMP", "HOME", "USERPROFILE", "LANG", "LC_ALL", "COMSPEC"}
    return {key: value for key, value in os.environ.items() if key.upper() in keep}


def _limit_resources():  # pragma: no cover — работает только на Linux/macOS (например, на VPS)
    import resource

    limits = (
        (resource.RLIMIT_CPU, TIMEOUT + 2),
        (resource.RLIMIT_AS, 1024 * 2**20),
        (resource.RLIMIT_FSIZE, 20 * 2**20),
    )
    for kind, value in limits:
        try:
            resource.setrlimit(kind, (value, value))
        except (ValueError, OSError):
            pass


def run_child(mode, workdir, params, stdin="", timeout=TIMEOUT):
    """Запускает runner.py в отдельном процессе. Возвращает CompletedProcess или None при таймауте."""
    meta = workdir + "_meta"
    os.makedirs(meta, exist_ok=True)
    params_path = os.path.join(meta, "params.json")
    with open(params_path, "w", encoding="utf-8") as file:
        json.dump(params, file, ensure_ascii=False)
    options = {"creationflags": subprocess.CREATE_NO_WINDOW} if os.name == "nt" else {"preexec_fn": _limit_resources}
    try:
        return subprocess.run(
            [sys.executable, "-I", "-X", "utf8", RUNNER, mode, params_path],
            cwd=workdir,
            input=stdin,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
            env=child_env(),
            **options,
        )
    except subprocess.TimeoutExpired:
        return None


def explain(exc_name):
    hint = EXPLAIN.get(exc_name)
    return f"\n💡 {hint}" if hint else ""


def clean_stderr(err):
    """Убирает служебные метки runner.py из stderr."""
    return re.sub(r"\n?__(EXC__\w+|LIMIT__)", "", err).strip()


# ------------------------------------------------------------------ тест «программа»


def describe_io(test):
    """Что подавалось программе: ввод, аргументы, файлы."""
    parts = []
    if test.get("args") is not None:
        args = " ".join(test["args"])
        parts.append(f"Запуск: <code>python solution.py {esc(args)}</code>".rstrip())
    for name, content in test.get("files", {}).items():
        if isinstance(content, str):
            parts.append(f"Файл <code>{esc(name)}</code>:{pre(content, 300)}")
    if "input" in test or not parts:
        parts.append(f"Ввод:{pre(test.get('input', ''), 400)}")
    return "\n".join(parts)


def output_hint(got, want):
    if got.lower() == want.lower():
        return "\n💡 Отличается только регистр букв."
    if got.replace(" ", "") == want.replace(" ", ""):
        return "\n💡 Отличаются только пробелы."
    if want and want in got:
        return "\n💡 Нужный ответ есть, но программа печатает что-то лишнее. Приглашения в input() не считаются, а лишние print считаются."
    if got and got in want:
        return "\n💡 Программа напечатала только часть ответа."
    return ""


def compare_output(test, out):
    got = normalize(out)
    if "check" in test:  # своя функция проверки (например, для случайного вывода)
        problem = test["check"](got)
        return None if problem is None else f"{problem}\nТвоя программа вывела:{pre(got)}"
    want_raw = test.get("output", "")
    mode = test.get("match", "exact")
    if mode == "regex":
        if re.fullmatch(want_raw, got):
            return None
        return f"Вывод не подходит под формат.\nТвоя программа вывела:{pre(got)}"
    want = normalize(want_raw)
    if (mode == "contains" and want in got) or (mode == "exact" and got == want):
        return None
    return f"Ожидался вывод:{pre(want)}Твоя программа вывела:{pre(got)}" + output_hint(got, want)


def compare_file(workdir, name, want):
    path = os.path.join(workdir, *name.split("/"))
    if not os.path.isfile(path):
        return f"Программа не создала файл <code>{esc(name)}</code>."
    with open(path, "rb") as file:
        got_text = file.read().decode("utf-8", errors="replace")
    if name.endswith(".json"):
        try:
            got = json.loads(got_text)
        except ValueError:
            return f"В <code>{esc(name)}</code> не корректный JSON:{pre(got_text)}"
        expected = json.loads(want) if isinstance(want, str) else want
        if got == expected:
            return None
        return (
            f"Содержимое <code>{esc(name)}</code> не совпадает.\n"
            f"Ожидалось:{pre(json.dumps(expected, ensure_ascii=False, indent=2))}"
            f"Получено:{pre(json.dumps(got, ensure_ascii=False, indent=2))}"
        )
    if name.endswith(".csv"):
        rows = lambda text: [row for row in csv.reader(io.StringIO(normalize(text))) if row]  # noqa: E731
        if rows(got_text) == rows(want):
            return None
    elif normalize(got_text) == normalize(want):
        return None
    return (
        f"Содержимое <code>{esc(name)}</code> не совпадает.\n"
        f"Ожидалось:{pre(normalize(want))}Получено:{pre(normalize(got_text))}"
    )


def io_once(workdir, test, name, context):
    """Один запуск программы. Возвращает (Outcome при провале или None, вывод)."""
    params = {"file": "solution.py", "args": test.get("args", [])}
    limit = test.get("timeout", TIMEOUT)
    proc = run_child("io", workdir, params, stdin=test.get("input", ""), timeout=limit)
    if proc is None:
        return Outcome(False, name, context + TIMEOUT_TEXT.format(limit=limit), timeout=True), ""
    out, err = proc.stdout, proc.stderr
    if "__LIMIT__" in err:
        return Outcome(False, name, context + LIMIT_TEXT), out
    crash = re.search(r"__EXC__(\w+)", err)
    if test.get("exit") == "error":
        if crash:
            return Outcome(False, name, context + "Ожидался выход через <code>sys.exit(\"…\")</code>, "
                           f"а программа упала:{pre(clean_stderr(err))}" + explain(crash.group(1))), out
        if proc.returncode == 0:
            return Outcome(False, name, context + "Ожидалось, что программа завершится с ошибкой через "
                           f"<code>sys.exit(\"…\")</code>, а она отработала как обычно. Вывод:{pre(normalize(out))}"), out
        want = test.get("output", "")
        if want and want.lower() not in (err + out).lower():
            return Outcome(False, name, context + f"Сообщение об ошибке должно содержать «{esc(want)}».\n"
                           f"Получено:{pre(clean_stderr(err) or normalize(out))}"), out
        return None, out
    if proc.returncode != 0:
        if crash:
            text = f"💥 Программа упала с ошибкой:{pre(clean_stderr(err), 900)}" + explain(crash.group(1))
        else:
            text = f"Программа завершилась с кодом {proc.returncode} (sys.exit):{pre(clean_stderr(err) or normalize(out))}"
        return Outcome(False, name, context + text), out
    problem = compare_output(test, out)
    if problem:
        return Outcome(False, name, context + problem), out
    for file_name, want in test.get("expect_files", {}).items():
        problem = compare_file(workdir, file_name, want)
        if problem:
            return Outcome(False, name, context + problem), out
    return None, out


def io_test(workdir, test, name):
    """Тест программы. С ключом repeat программа запускается несколько раз (для случайного вывода),
    а функция check_all(список_выводов) проверяет, что выводы правда разные."""
    context = describe_io(test) + "\n"
    outputs = []
    for _ in range(test.get("repeat", 1)):
        failure, out = io_once(workdir, test, name, context)
        if failure:
            return failure
        outputs.append(normalize(out))
    if "check_all" in test:
        problem = test["check_all"](outputs)
        if problem:
            return Outcome(False, name, context + problem)
    return Outcome(True, name)


# ------------------------------------------------------------------ тест «выражение»


def describe_expr(test):
    code = (test.get("setup", "").strip() + "\n" + test["expr"]).strip()
    return f"Проверка:{pre(code, 500)}"


def expr_test(workdir, test, name):
    meta_result = os.path.join(workdir + "_meta", "result.json")
    params = {"file": "solution.py", "setup": test.get("setup", ""), "expr": test["expr"], "result_file": meta_result}
    if "raises" in test:
        params["raises"] = test["raises"]
    else:
        params["expected"] = repr(test["expected"])
    limit = test.get("timeout", TIMEOUT)
    proc = run_child("expr", workdir, params, timeout=limit)
    context = describe_expr(test)
    if proc is None:
        return Outcome(False, name, context + TIMEOUT_TEXT.format(limit=limit), timeout=True)
    try:
        with open(meta_result, encoding="utf-8") as file:
            result = json.load(file)
    except (OSError, ValueError):
        err = clean_stderr(proc.stderr) or "(нет подробностей)"
        return Outcome(False, name, context + ("Проверка аварийно завершилась." + pre(err)))
    status = result["status"]
    printed = normalize(result.get("printed", ""))
    if status == "ok":
        return Outcome(True, name)
    if status == "wrong":
        text = context + f"Ожидалось: <code>{esc(repr(test['expected']))}</code>\n" \
                         f"Получено: <code>{esc(result['got'])}</code>"
        if result["got"] == "None" and printed:
            text += "\n💡 Функция печатает результат через print(), а его нужно вернуть через <code>return</code>."
        elif result["got"] == "None":
            text += "\n💡 Функция ничего не вернула. Не забыл <code>return</code>?"
        elif type(test["expected"]).__name__ != result.get("got_type"):
            text += f"\n💡 Тип не тот: нужен <code>{type(test['expected']).__name__}</code>, " \
                    f"а получен <code>{result.get('got_type')}</code>."
        return Outcome(False, name, text)
    if status == "no_exception":
        return Outcome(False, name, context + f"Ожидалось исключение <code>{test['raises']}</code>, но его не было. "
                       f"Результат: <code>{esc(result['got'])}</code>")
    if status == "wrong_exception":
        return Outcome(False, name, context + f"Ожидалось <code>{test['raises']}</code>, а возникло другое:"
                       + pre(result["error"]))
    if status == "import_error":
        text = "💥 Код упал ещё при загрузке, до вызова функций:" + pre(result["error"], 900)
        if result["exc"] == "EOFError":
            text += ("\n💡 При проверке функций код импортируется, и вызовы <code>input()</code> на верхнем "
                     "уровне ломают проверку. Оберни запуск так:\n<code>if __name__ == \"__main__\":\n    main()</code>")
        else:
            text += explain(result["exc"])
        return Outcome(False, name, text)
    return Outcome(False, name, context + "💥 При вычислении возникла ошибка:" + pre(result["error"], 900)
                   + explain(result.get("exc", "")))


# ------------------------------------------------------------------ задачи на написание тестов


def pytest_task(task, code, filename):
    report = Report()
    implementations = [("правильная реализация", task["impl"]), *task["mutants"]]
    for index, (label, impl) in enumerate(implementations):
        with tempfile.TemporaryDirectory(prefix="pybot_", ignore_cleanup_errors=True) as tmp:
            workdir = os.path.join(tmp, "run")
            os.makedirs(workdir)
            write_file(workdir, task["module"] + ".py", textwrap.dedent(impl))
            write_file(workdir, filename, code)
            write_file(workdir, "pytest.ini", "[pytest]\n")
            proc = run_child("pytest", workdir, {"file": filename}, timeout=PYTEST_TIMEOUT)
        output = normalize(proc.stdout) if proc else ""
        if index == 0:
            name = "Твои тесты на правильной реализации"
            if proc is None:
                report.outcomes.append(Outcome(False, name, TIMEOUT_TEXT.format(limit=PYTEST_TIMEOUT), True))
            elif proc.returncode == 5:
                report.outcomes.append(Outcome(False, name, "Не найдено ни одного теста. Функции должны "
                                               f"называться <code>test_…</code>, а файл — <code>{filename}</code>."))
            elif proc.returncode != 0:
                report.outcomes.append(Outcome(False, name, "На <b>правильной</b> реализации твои тесты падают, "
                                               "значит ошибка в самих тестах:" + pre(tail(output), 1500)))
            else:
                report.outcomes.append(Outcome(True, name))
            if not report.outcomes[0].ok:
                return report  # нет смысла ловить ошибки, пока тесты падают на правильном коде
            continue
        name = f"Ошибка №{index}: {label}"
        if proc is not None and proc.returncode == 1:
            report.outcomes.append(Outcome(True, name))
        elif proc is not None and proc.returncode == 0:
            report.outcomes.append(Outcome(False, name, f"Твои тесты <b>не заметили</b> ошибку: {esc(label)}.\n"
                                           "💡 Добавь тест, который упадёт на такой реализации."))
        else:
            detail = pre(tail(output), 1200) if proc else TIMEOUT_TEXT.format(limit=PYTEST_TIMEOUT)
            report.outcomes.append(Outcome(False, name, "Прогон тестов закончился ошибкой:" + detail))
    return report


def tail(output):
    """Самое полезное из вывода pytest: секция FAILURES/ERRORS и итог."""
    for marker in ("= FAILURES =", "= ERRORS ="):
        position = output.find(marker)
        if position != -1:
            return output[output.rfind("\n", 0, position) + 1:]
    return output[-1500:]


# ------------------------------------------------------------------ главное


def check(task, code):
    """Проверяет решение задачи. Возвращает Report."""
    code = clean_code(code)
    if not code.strip():
        return Report(fatal="Пустое сообщение. Пришли код решения.")
    if len(code) > MAX_CODE:
        return Report(fatal=f"Слишком длинный код (больше {MAX_CODE} символов).")
    is_pytest = task.get("kind") == "pytest"
    filename = f"test_{task['module']}.py" if is_pytest else "solution.py"
    problem = syntax_problem(code, filename)
    if problem:
        return Report(fatal=problem)
    if is_pytest:
        return pytest_task(task, code, filename)
    report = Report()
    for number, test in enumerate(task["tests"], 1):
        with tempfile.TemporaryDirectory(prefix="pybot_", ignore_cleanup_errors=True) as tmp:
            workdir = os.path.join(tmp, "run")
            os.makedirs(workdir)
            write_file(workdir, "solution.py", code)
            for name, content in test.get("files", {}).items():
                write_file(workdir, name, content)
            runner = expr_test if "expr" in test else io_test
            outcome = runner(workdir, test, f"Тест {number}")
        report.outcomes.append(outcome)
        if outcome.timeout:  # после бесконечного цикла остальные тесты только зря ждать
            report.skipped = len(task["tests"]) - number
            break
    return report


def report_html(report):
    """Отчёт для Telegram: полоска ✅/❌ и подробности первой ошибки."""
    if report.fatal:
        text = report.fatal
    elif not report.outcomes:
        text = "У этой задачи нет тестов."
    else:
        marks = "".join("✅" if outcome.ok else "❌" for outcome in report.outcomes) + "▫️" * report.skipped
        if report.ok:
            return f"{marks}\nВсе проверки пройдены: {report.passed}/{report.total}"
        failed = next(outcome for outcome in report.outcomes if not outcome.ok)
        text = f"{marks}\nПройдено: {report.passed} из {report.total}\n\n❌ <b>{esc(failed.name)}</b>\n{failed.details}"
        if report.skipped:
            text += "\n\n▫️ Остальные тесты не запускались."
    return re.sub(r"\n{3,}", "\n\n", text).strip()  # не больше одной пустой строки подряд


def report_text(report):
    """Тот же отчёт без HTML-тегов — для консоли (python bot.py --check)."""
    return html.unescape(re.sub(r"<[^>]+>", "", report_html(report)))

runner.py:
"""Исполнитель кода ученика. Запускается в ОТДЕЛЬНОМ процессе из checker.py:

    python -I -X utf8 runner.py <режим> <params.json>

Режимы:
    io     — запустить solution.py как обычную программу (stdin → stdout);
    expr   — импортировать solution.py и вычислить выражение из теста
             (так проверяются функции и классы);
    pytest — прогнать тесты ученика настоящим pytest.

Результат режима expr записывается в JSON-файл params["result_file"].
Файл специально ничего не импортирует из проекта бота: код ученика
выполняется отдельно от самого бота.
"""

import ast
import builtins
import io
import json
import math
import os
import runpy
import sys
import traceback

OUTPUT_LIMIT = 64_000  # сколько символов программе разрешено напечатать
SHOW_FILES = {"<тест>"}  # из каких файлов показывать строки трейсбека


class OutputLimitExceeded(Exception):
    """Программа напечатала слишком много (скорее всего, бесконечный цикл с print)."""


class LimitedWriter(io.TextIOBase):
    """Обёртка над stdout, которая не даёт напечатать больше OUTPUT_LIMIT символов."""

    def __init__(self, inner, limit=OUTPUT_LIMIT):
        self.inner = inner
        self.left = limit

    def writable(self):
        return True

    def write(self, text):
        self.left -= len(text)
        if self.left < 0:
            raise OutputLimitExceeded
        return self.inner.write(text)

    def flush(self):
        self.inner.flush()

    @property
    def encoding(self):
        return "utf-8"


def quiet_input(prompt=""):
    """Как input(), только без печати приглашения.

    Благодаря этому input("Как тебя зовут? ") не попадает в вывод
    и не мешает сравнивать ответ программы с ожидаемым.
    """
    line = sys.stdin.readline()
    if not line:
        raise EOFError("EOF when reading a line")
    return line.removesuffix("\n")


def format_error(exc):
    """Короткий трейсбек: только строки из кода ученика, без внутренностей runpy."""
    frames = [
        frame
        for frame in traceback.extract_tb(exc.__traceback__)
        if os.path.basename(frame.filename) in SHOW_FILES
    ]
    parts = []
    if frames:
        parts.append("Traceback (most recent call last):\n")
        parts.extend(traceback.format_list(frames))
    parts.extend(traceback.format_exception_only(type(exc), exc))
    return "".join(parts).rstrip()


def show(value):
    """repr() значения, но не длиннее 500 символов и без падений."""
    try:
        text = repr(value)
    except Exception as exc:  # у объекта ученика может быть сломанный __repr__
        text = f"<repr() упал: {type(exc).__name__}>"
    return text if len(text) <= 500 else text[:500] + "…"


def same(got, expected):
    """Сравнение результата с ожидаемым: дроби с допуском, типы — строго."""
    if isinstance(expected, bool) or isinstance(got, bool):
        return type(got) is type(expected) and got == expected
    if isinstance(expected, float) or isinstance(got, float):
        numbers = (int, float)
        return (
            isinstance(got, numbers)
            and isinstance(expected, numbers)
            and math.isclose(got, expected, rel_tol=1e-6, abs_tol=1e-9)
        )
    if isinstance(expected, (list, tuple)):
        return (
            type(got) is type(expected)
            and len(got) == len(expected)
            and all(same(a, b) for a, b in zip(got, expected))
        )
    if isinstance(expected, dict):
        return (
            isinstance(got, dict)
            and got.keys() == expected.keys()
            and all(same(got[key], expected[key]) for key in expected)
        )
    return type(got) is type(expected) and got == expected


def run_io(params):
    """Запуск как обычной программы: python solution.py аргументы < ввод."""
    target = params["file"]
    SHOW_FILES.add(target)
    sys.argv = [target, *params.get("args", [])]
    sys.stdout = LimitedWriter(sys.stdout)
    try:
        runpy.run_path(target, run_name="__main__")
    except SystemExit:
        raise  # sys.exit() ученика — нормальное завершение со своим кодом
    except OutputLimitExceeded:
        sys.stderr.write("\n__LIMIT__")
        sys.exit(3)
    except BaseException as exc:
        sys.stderr.write(format_error(exc) + "\n__EXC__" + type(exc).__name__)
        sys.exit(1)


def evaluate(params):
    """Импортирует код ученика и вычисляет выражение теста. Возвращает словарь-результат."""
    try:
        namespace = runpy.run_path(params["file"], run_name="solution")
    except BaseException as exc:
        return {"status": "import_error", "exc": type(exc).__name__, "error": format_error(exc)}
    try:
        if params.get("setup"):
            exec(compile(params["setup"], "<тест>", "exec"), namespace)
        code = compile(params["expr"], "<тест>", "eval")
        if params.get("raises"):
            try:
                value = eval(code, namespace)
            except BaseException as exc:
                if any(cls.__name__ == params["raises"] for cls in type(exc).__mro__):
                    return {"status": "ok"}
                return {"status": "wrong_exception", "exc": type(exc).__name__, "error": format_error(exc)}
            return {"status": "no_exception", "got": show(value)}
        value = eval(code, namespace)
    except BaseException as exc:
        return {"status": "error", "exc": type(exc).__name__, "error": format_error(exc)}
    if same(value, ast.literal_eval(params["expected"])):
        return {"status": "ok"}
    return {"status": "wrong", "got": show(value), "got_type": type(value).__name__}


def run_expr(params):
    SHOW_FILES.add(params["file"])
    captured = io.StringIO()
    sys.stdout = LimitedWriter(captured)
    sys.stdin = io.StringIO("")  # если код при импорте вызовет input(), будет EOFError
    result = evaluate(params)
    sys.stdout = sys.__stdout__
    result["printed"] = captured.getvalue()[-1000:]
    with open(params["result_file"], "w", encoding="utf-8") as file:
        json.dump(result, file, ensure_ascii=False)


def run_pytest(params):
    """Прогон тестов ученика настоящим pytest. Код выхода: 0 — всё прошло, 1 — есть падения."""
    import pytest

    sys.dont_write_bytecode = True
    sys.stdin = io.StringIO("")
    options = ["-q", "--tb=short", "--no-header", "-p", "no:cacheprovider", "-p", "no:faulthandler"]
    code = pytest.main([params["file"], *options, *params.get("pytest_args", [])])
    sys.exit(int(code))


def main():
    mode, params_path = sys.argv[1], sys.argv[2]
    with open(params_path, encoding="utf-8") as file:
        params = json.load(file)
    sys.argv = sys.argv[:1]
    sys.path.insert(0, os.getcwd())  # чтобы работали импорты файлов из папки задачи
    builtins.input = quiet_input
    {"io": run_io, "expr": run_expr, "pytest": run_pytest}[mode](params)


if __name__ == "__main__":
    main()

webcheck.py:
"""Проверка решений внутри Mini App. Этот модуль загружается в Pyodide (worker.js).

Используется тот же checker.py, что и в боте, только код ученика
выполняется в этом же интерпретаторе (webrunner.py), а не в отдельном процессе.
"""

import contextlib
import json
import tempfile

import checker
import course
import webrunner

RUN_TIMEOUT = 5  # секунд на «▶ Запустить»


@contextlib.contextmanager
def in_process():
    """На время проверки checker запускает код через webrunner, а потом всё возвращается как было."""
    original = checker.run_child
    checker.run_child = webrunner.run_child
    try:
        yield
    finally:
        checker.run_child = original


def check(task_id, code):
    """«✅ Проверить»: прогнать решение по тестам задачи."""
    with in_process():
        report = checker.check(course.TASKS[task_id], code)
    return json.dumps(
        {"ok": report.ok, "passed": report.passed, "total": report.total, "html": checker.report_html(report)},
        ensure_ascii=False,
    )


def run(code, stdin=""):
    """«▶ Запустить»: выполнить программу со своим вводом и показать, что она напечатала."""
    code = checker.clean_code(code)
    problem = checker.syntax_problem(code, "solution.py")
    if problem:
        return json.dumps({"ok": False, "html": problem}, ensure_ascii=False)
    if stdin and not stdin.endswith("\n"):
        stdin += "\n"
    with tempfile.TemporaryDirectory(ignore_cleanup_errors=True) as folder:
        checker.write_file(folder, "solution.py", code)
        proc = webrunner.run_child("io", folder, {"file": "solution.py", "args": []}, stdin=stdin,
                                   timeout=RUN_TIMEOUT, echo=True)
    if proc is None:
        return json.dumps({"ok": False, "html": checker.TIMEOUT_TEXT.format(limit=RUN_TIMEOUT)}, ensure_ascii=False)
    output = checker.normalize(proc.stdout)
    html = f"<b>Вывод программы:</b>{checker.pre(output or '(ничего не напечатано)', 3000)}"
    crash = checker.re.search(r"__EXC__(\w+)", proc.stderr)
    if crash:
        html += f"💥 <b>Ошибка:</b>{checker.pre(checker.clean_stderr(proc.stderr), 1500)}" + checker.explain(crash.group(1))
        if crash.group(1) == "EOFError":
            html += "\n💡 Для каждого <code>input()</code> нужна своя строка в поле «Ввод»."
    elif proc.returncode != 0:
        html += f"Программа завершилась через <code>sys.exit</code>:{checker.pre(checker.clean_stderr(proc.stderr))}"
    return json.dumps({"ok": proc.returncode == 0, "html": checker.re.sub(r"\n{3,}", "\n\n", html)}, ensure_ascii=False)

course/__init__.py:
"""Курс: 10 разделов = 10 лекций CS50P.

Каждый раздел лежит в своём файле (s0_functions.py … s9_etcetera.py) и описан
словарём SECTION. Здесь разделы собираются вместе, нумеруются и проверяются.

    SECTIONS — список разделов по порядку
    TOPICS   — {"2.3": тема}
    TASKS    — {"twttr": задача}
    ORDER    — id всех задач в порядке прохождения курса
"""

import importlib

MODULES = [
    "s0_functions",
    "s1_conditionals",
    "s2_loops",
    "s3_exceptions",
    "s4_libraries",
    "s5_unit_tests",
    "s6_file_io",
    "s7_regex",
    "s8_oop",
    "s9_etcetera",
]

SECTIONS = []
TOPICS = {}
TASKS = {}
ORDER = []

TASK_KEYS = {"id", "title", "level", "text", "hint", "solution"}


def _load():
    for name in MODULES:
        try:
            module = importlib.import_module(f"{__name__}.{name}")
        except ModuleNotFoundError as exc:
            if exc.name == f"{__name__}.{name}":
                continue  # раздел ещё не написан
            raise
        SECTIONS.append(module.SECTION)

    for number, section in enumerate(SECTIONS):
        section["num"] = number
        starts = [start for start, _ in section.get("chapters", [])]
        for index, topic in enumerate(section["topics"], 1):
            topic["id"] = f"{number}.{index}"
            topic["section"] = section
            TOPICS[topic["id"]] = topic
            for start in topic.get("video", []):
                if start not in starts:
                    raise ValueError(f"Тема {topic['id']}: нет главы с началом {start} с")
            for task_index, task in enumerate(topic["tasks"], 1):
                missing = TASK_KEYS - task.keys()
                if missing:
                    raise ValueError(f"Задача {task.get('id')}: не хватает полей {missing}")
                if task["id"] in TASKS:
                    raise ValueError(f"Повторяется id задачи: {task['id']}")
                if task.get("kind") == "pytest":
                    if not {"module", "impl", "mutants"} <= task.keys():
                        raise ValueError(f"Задача {task['id']}: для pytest нужны module, impl и mutants")
                elif not task.get("tests"):
                    raise ValueError(f"Задача {task['id']}: нет тестов")
                task["topic"] = topic
                task["num"] = task_index
                TASKS[task["id"]] = task
                ORDER.append(task["id"])


def chapters(topic):
    """Главы лекции для темы: [(начало в секундах, название, длительность в секундах)]."""
    section = topic["section"]
    all_chapters = section.get("chapters", [])
    starts = [start for start, _ in all_chapters]
    result = []
    for start in topic.get("video", []):
        index = starts.index(start)
        end = all_chapters[index + 1][0] if index + 1 < len(all_chapters) else section["length"]
        result.append((start, all_chapters[index][1], end - start))
    return result


def next_topic(topic):
    """Следующая тема курса или None, если эта последняя."""
    ids = list(TOPICS)
    position = ids.index(topic["id"])
    return TOPICS[ids[position + 1]] if position + 1 < len(ids) else None


def next_task(task):
    """Следующая задача курса или None."""
    position = ORDER.index(task["id"])
    return TASKS[ORDER[position + 1]] if position + 1 < len(ORDER) else None


def plural(n, one, few, many):
    """plural(84, "задача", "задачи", "задач") → "84 задачи"."""
    if n % 10 == 1 and n % 100 != 11:
        return f"{n} {one}"
    if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14:
        return f"{n} {few}"
    return f"{n} {many}"


def size():
    """«10 разделов, 43 темы, 84 задачи» — с правильными окончаниями."""
    return ", ".join([
        plural(len(SECTIONS), "раздел", "раздела", "разделов"),
        plural(len(TOPICS), "тема", "темы", "тем"),
        plural(len(ORDER), "задача", "задачи", "задач"),
    ])


_load()

course/helpers.py:
"""Короткие функции для описания тестов в файлах разделов.

    prog("ввод", "вывод")                   — тест программы: подаём ввод, сравниваем вывод
    prog(args=["a.py"], files={...}, ...)   — плюс аргументы командной строки, файлы и т.д.
    expr("square(3)", 9)                    — тест функции: выражение должно дать значение
    expr("j.size", 3, setup="j = Jar()")    — перед выражением можно выполнить код
    raises("Jar(-1)", "ValueError")         — выражение должно бросить исключение
"""


def prog(input="", output="", **extra):
    if input and not input.endswith("\n"):
        input += "\n"
    return {"input": input, "output": output, **extra}


def expr(expression, expected, setup=""):
    return {"setup": setup, "expr": expression, "expected": expected}


def raises(expression, exception="ValueError", setup=""):
    return {"setup": setup, "expr": expression, "raises": exception}


def yt(video_id, seconds=0):
    """Ссылка на YouTube с нужного момента."""
    return f"https://www.youtube.com/watch?v={video_id}" + (f"&t={seconds}s" if seconds else "")

