"""Раздел 8. Объектно-ориентированное программирование — CS50P Lecture 8."""

from .helpers import expr, raises

STUDENT = "s = Student('Иван', 'ИВТ-101')"

SECTION = {
    "title": "ООП: классы и объекты",
    "emoji": "🏗",
    "lecture": "Lecture 8 · Object-Oriented Programming",
    "video": "e4fwY9ZsxPw",
